fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Number of rows and columns in the input matrix
    let row_count = arr.len();
    let col_count = arr[0].len();

    // Initialize the output matrix with dimensions col_count x row_count
    // Each row in the output initially filled with zeros
    let mut result = vec![vec![0i8; row_count]; col_count];

    // Iterate over each element in arr and place it in the transposed position
    for i in 0..row_count {
        for j in 0..col_count {
            result[j][i] = arr[i][j];
        }
    }

    result
}